-- Lote 7 — homologação transacional. Tudo é revertido ao final.
BEGIN;
DO $$ DECLARE missing text[]; BEGIN SELECT array_agg(x) INTO missing FROM unnest(ARRAY['quotes','quote_versions','quote_items','quote_item_sizes','payment_term_templates','discount_approvals','proposal_access_tokens']) x WHERE to_regclass('public.'||x) IS NULL; IF missing IS NOT NULL THEN RAISE EXCEPTION 'Tabelas ausentes: %',missing; END IF; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['quotes','quote_versions','quote_items','quote_item_sizes','payment_term_templates','discount_approvals','proposal_access_tokens'] LOOP IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid=('public.'||t)::regclass) THEN RAISE EXCEPTION 'RLS ausente: %',t; END IF; END LOOP; IF has_table_privilege('anon','public.quotes','SELECT') OR has_table_privilege('anon','public.proposal_access_tokens','SELECT') THEN RAISE EXCEPTION 'anon possui acesso indevido'; END IF; IF NOT has_function_privilege('anon','public.get_public_proposal(text)','EXECUTE') OR has_function_privilege('anon','public.quote_move_stage(uuid,text)','EXECUTE') THEN RAISE EXCEPTION 'Privilégios das RPCs públicas inválidos'; END IF; END $$;
DO $$ DECLARE f text; BEGIN FOREACH f IN ARRAY ARRAY['save_quote_draft','request_quote_approval','decide_quote_approval','send_quote_version','get_public_proposal','record_proposal_view','respond_to_proposal','approve_quote_version','create_quote_version','duplicate_quote','convert_quote_to_order','get_quote_dashboard_stats','run_commercial_daily_check','payment_term_rules_valid'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=f) THEN RAISE EXCEPTION 'RPC ausente: %',f; END IF; END LOOP; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_indexes WHERE indexname='pedidos_source_quote_unique_idx') THEN RAISE EXCEPTION 'Idempotência da conversão ausente'; END IF; IF NOT EXISTS(SELECT 1 FROM public.payment_term_templates WHERE active AND public.payment_term_rules_valid(rules)) THEN RAISE EXCEPTION 'Condições de pagamento ausentes ou inválidas'; END IF; IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='commercial_settings' AND column_name='minimum_margin_percent') THEN RAISE EXCEPTION 'Margem mínima ausente'; END IF; IF EXISTS(SELECT 1 FROM unnest(ARRAY['quotes.view','quotes.create','quotes.update','quotes.approve']) AS required(code) WHERE NOT EXISTS(SELECT 1 FROM public.permissions p WHERE p.code=required.code)) THEN RAISE EXCEPTION 'Permissions de orçamento incompletas'; END IF; END $$;
DO $$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.convert_quote_to_order(uuid)'::regprocedure) INTO body; IF body NOT LIKE '%FOR UPDATE%' OR body NOT LIKE '%INSERT INTO public.accounts_receivable%' OR body LIKE '%INSERT INTO public.payments%' THEN RAISE EXCEPTION 'Conversão sem lock, recebíveis ou separação de pagamentos'; END IF; SELECT pg_get_functiondef('public.get_public_proposal(text)'::regprocedure) INTO body; IF body LIKE '%estimated_cost%' OR body LIKE '%margin_percent%' OR body LIKE '%internal_notes%' THEN RAISE EXCEPTION 'DTO público expõe dado interno'; END IF; END $$;
ROLLBACK;
